import { assertNoCockpitLeak, compileIntent, hasCapability, legacyProjection, specificityOracle, type CompilerIR } from './intent-compiler';

export type AppField = {
  key: string;
  label: string;
  type: 'text' | 'number' | 'date' | 'status' | 'email';
  required: boolean;
};

export type ProductBrief = {
  productName: string;
  summary: string;
  appType: 'website' | 'crm' | 'commerce' | 'shopping' | 'plants' | 'entertainment' | 'booking' | 'project' | 'content' | 'operations' | 'generic';
  entity: { singular: string; plural: string; fields: AppField[] };
  roles: string[];
  workflows: string[];
  pages: string[];
  palette: { accent: string; accentSoft: string; background: string };
  compiler: CompilerIR;
};

export type GeneratedFile = { path: string; content: string };

