function field(key: string, label: string, type: AppField['type'] = 'text'): AppField {
  return { key, label, type, required: true };
}

function cleanText(value: unknown, fallback: string, max = 120) {
  return typeof value === 'string' && value.trim() ? value.trim().slice(0, max) : fallback;
}

function safeKey(value: unknown, fallback: string) {
  const normalized = cleanText(value, fallback, 40).normalize('NFKD').replace(/[^a-zA-Z0-9]+(.)?/g, (_match, next: string | undefined) => next ? next.toUpperCase() : '').replace(/^[^a-zA-Z]+/, '');
  return normalized || fallback;
}

function safeColor(value: unknown, fallback: string) {
  return typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value) ? value : fallback;
}

function stringList(value: unknown, fallback: string[], max = 8) {
  if (!Array.isArray(value)) return fallback;
  const result = value.filter((item): item is string => typeof item === 'string' && Boolean(item.trim())).map((item) => item.trim().slice(0, 100)).slice(0, max);
  return result.length ? result : fallback;
}

function isBareApplicationRequest(name: string, description: string) {
  const bare = /^(?:mi\s+)?(?:crei|crea|costruisci|fammi|vorrei)\s+(?:un['’]?\s*)?(?:app|applicazione)(?:\s+(?:mobile|bella|figa))?[.!?]?$/i;
  const normalize = (value: string) => value.replace(/^applicazione\s+full-stack\s*:\s*/i, '').replace(/\s+/g, ' ').trim();
  return bare.test(normalize(name)) || bare.test(normalize(description));
}

export function inferProductBrief(name: string, description: string, candidate?: unknown): ProductBrief {
  const source = `${name} ${description}`.toLowerCase();
  const bareRequest = isBareApplicationRequest(name, description);
  const focusDomain = {
    type: 'project' as const,
    singular: 'Attività',
    plural: 'Attività',
    fields: [field('title', 'Titolo'), field('category', 'Area'), field('dueDate', 'Scadenza', 'date'), field('status', 'Stato', 'status')],
    workflows: ['Oggi', 'In corso', 'Completato'],
  };
  const domain = (bareRequest ? focusDomain : domainCatalog.find((item) => item.terms.some((term) => source.includes(term)))) ?? {
    type: 'generic' as const,
    singular: 'Attività',
    plural: 'Attività',
    fields: [field('title', 'Titolo'), field('category', 'Area'), field('dueDate', 'Scadenza', 'date'), field('status', 'Stato', 'status')],
    workflows: ['Oggi', 'In corso', 'Completato'],
  };
  const candidateRaw = candidate && typeof candidate === 'object' ? candidate as Record<string, unknown> : {};
  const candidateEntity = candidateRaw.entity && typeof candidateRaw.entity === 'object' ? candidateRaw.entity as Record<string, unknown> : {};
  const stalePlaceholder = /^(?:elemento|elementi)$/i.test(String(candidateEntity.singular ?? '')) || /^(?:elemento|elementi)$/i.test(String(candidateEntity.plural ?? ''));
  const raw = bareRequest || stalePlaceholder ? {} : candidateRaw;
  const entity = raw.entity && typeof raw.entity === 'object' ? raw.entity as Record<string, unknown> : {};
  const allowedTypes: ProductBrief['appType'][] = ['website', 'crm', 'commerce', 'shopping', 'plants', 'entertainment', 'booking', 'project', 'content', 'operations', 'generic'];
  const rawType = typeof raw.appType === 'string' && allowedTypes.includes(raw.appType as ProductBrief['appType']) ? raw.appType as ProductBrief['appType'] : null;
  const useDomainDefaults = domain.type !== 'generic' && (!rawType || rawType === 'generic');
  const rawFields = useDomainDefaults ? [] : Array.isArray(entity.fields) ? entity.fields : [];
  const fields = rawFields.map((item, index): AppField | null => {
    if (!item || typeof item !== 'object') return null;
    const input = item as Record<string, unknown>;
    const type = ['text', 'number', 'date', 'status', 'email'].includes(String(input.type)) ? String(input.type) as AppField['type'] : 'text';
    return { key: safeKey(input.key, `field${index + 1}`), label: cleanText(input.label, `Campo ${index + 1}`, 50), type, required: input.required !== false };
  }).filter((item): item is AppField => Boolean(item)).slice(0, 8);
  const statusField = (fields.length ? fields : domain.fields).some((item) => item.type === 'status');
  const normalizedFields = fields.length ? [...fields] : [...domain.fields];
  if (!statusField && normalizedFields.length < 8) normalizedFields.push(field('status', 'Stato', 'status'));
  const requestedType = rawType === 'generic' && domain.type !== 'generic' ? domain.type : rawType ?? domain.type;
  const isPlantDefault = domain.type === 'plants' && useDomainDefaults;
  const isEntertainmentDefault = domain.type === 'entertainment' && useDomainDefaults;
  const isFocusDefault = bareRequest && useDomainDefaults;
  const legacy = {
    productName: isPlantDefault ? 'VerdeVivo' : isEntertainmentDefault ? 'CineMagic' : isFocusDefault ? 'Orbit' : cleanText(raw.productName, name, 80),
    summary: isPlantDefault ? 'Cura le tue piante, pianifica le annaffiature e controlla il loro benessere in un solo spazio.' : isEntertainmentDefault ? 'Scopri film e cartoni Disney, esplora le collezioni e salva i tuoi titoli preferiti.' : isFocusDefault ? 'Organizza ciò che conta oggi, mantieni il focus e porta avanti i tuoi progetti con chiarezza.' : cleanText(raw.summary, description || `Gestione operativa di ${domain.plural.toLowerCase()}.`, 280),
    appType: requestedType,
    entity: {
      singular: useDomainDefaults ? domain.singular : cleanText(entity.singular, domain.singular, 50),
      plural: useDomainDefaults ? domain.plural : cleanText(entity.plural, domain.plural, 50),
      fields: normalizedFields,
    },
    roles: useDomainDefaults ? (isPlantDefault ? ['Proprietario', 'Giardiniere'] : isEntertainmentDefault ? ['Spettatore', 'Curatore'] : isFocusDefault ? ['Proprietario'] : ['Amministratore', 'Operatore']) : stringList(raw.roles, ['Amministratore', 'Operatore']),
    workflows: useDomainDefaults ? domain.workflows : stringList(raw.workflows, domain.workflows),
    pages: useDomainDefaults ? (isPlantDefault ? ['Oggi', 'Le mie piante', 'Calendario'] : isEntertainmentDefault ? ['Scopri', 'Film', 'Cartoni', 'La mia lista'] : isFocusDefault ? ['Oggi', 'Progetti', 'Focus', 'Profilo'] : ['Panoramica', domain.plural, 'Attività']) : stringList(raw.pages, ['Panoramica', domain.plural, 'Attività']),
    palette: {
      accent: isPlantDefault ? '#267052' : isEntertainmentDefault ? '#7c5cff' : isFocusDefault ? '#ff5a3c' : safeColor((raw.palette as Record<string, unknown> | undefined)?.accent, '#6d5dfc'),
      accentSoft: isPlantDefault ? '#e1f3e8' : isEntertainmentDefault ? '#201d43' : isFocusDefault ? '#fff0eb' : safeColor((raw.palette as Record<string, unknown> | undefined)?.accentSoft, '#ebe8ff'),
      background: isPlantDefault ? '#f3f7f3' : isEntertainmentDefault ? '#080b17' : isFocusDefault ? '#f7f4ef' : safeColor((raw.palette as Record<string, unknown> | undefined)?.background, '#f5f5f7'),
    },
  };
  const compiler = compileIntent(name, description, legacy);
  assertNoCockpitLeak(compiler);
  const projection = legacyProjection(compiler);
  const replaceGenericProjection = requestedType === 'generic' && legacy.entity.singular === 'Elemento';
  return {
    ...legacy,
    entity: replaceGenericProjection ? projection.entity as ProductBrief['entity'] : legacy.entity,
    roles: replaceGenericProjection ? projection.roles : legacy.roles,
    workflows: replaceGenericProjection ? projection.workflows : legacy.workflows,
    pages: replaceGenericProjection ? projection.pages : legacy.pages,
    compiler,
  };
}

export function productArchitectPrompt(name: string, description: string) {
  return `You are the FENIX Intent Compiler. Convert the request into one compact JSON object only, without markdown. Do not choose a dashboard unless the user explicitly asks for analytics, KPIs or a dashboard. Extract a concrete job-to-be-done, real domain nouns, verbs, actors, anti-jobs and a visible success scene before projecting compatibility fields. Schema: {"productName":string,"summary":string,"appType":"website|crm|commerce|shopping|plants|entertainment|booking|project|content|operations|generic","entity":{"singular":string,"plural":string,"fields":[{"key":camelCase,"label":string,"type":"text|number|date|status|email","required":boolean}]},"roles":[string],"workflows":[string],"pages":[string],"palette":{"accent":"#RRGGBB","accentSoft":"#RRGGBB","background":"#RRGGBB"},"intent":{"jobToBeDone":string,"antiJobs":[string],"domainNouns":[string],"verbs":[string],"setting":string,"successScene":string,"ambiguity":[string]}}. Include 4-6 specific fields and a status field. Never output Elemento, Elementi, Item 1, Alpha, Orione, Nova or Atlas. Request name: ${name.slice(0, 100)}. Request: ${description.slice(0, 4000)}`;
}

export function visualDesignerPrompt(brief: ProductBrief) {
  return `You are the FENIX Design Grammar pass. Refine copy, pages and accessible colors without changing the compiler intent, capabilities or first-paint archetype. Return one compact JSON object only, without markdown, using the same compatibility schema as the input. The first screen must enact the successScene and must not introduce dashboard chrome unless analytics.cockpit is present. Preserve the single Lucide family; express identity through layout archetype, material, density, geometry and motion. Never request emoji, Unicode icons or a mixed icon pack. Brief: ${JSON.stringify(brief).slice(0, 7000)}`;
}

export function softwareArchitectPlan(brief: ProductBrief) {
  return {
    architecture: 'intent-compiled dependency-free Node.js full-stack application',
    compiler: { version: brief.compiler.version, capabilities: brief.compiler.capabilities.nodes.map((node) => node.id), firstPaint: brief.compiler.interaction.firstPaint, archetype: brief.compiler.grammar.layoutBias[0] },
    runtime: 'Node.js HTTP server + SQLite',
    frontend: 'accessible responsive HTML/CSS/JavaScript client',
    backend: ['session authentication', 'role authorization', `CRUD API for ${brief.entity.plural}`, 'search and metrics API', 'health endpoint'],
    data: { engine: 'SQLite', entity: brief.entity, seedRows: 4 },
    quality: ['static contract', 'security lint', 'API scenario', 'HTTP integration', 'visual rendering', 'accessibility evidence'],
    routes: ['/api/health', '/api/session', '/api/login', '/api/logout', '/api/items', '/api/metrics'],
  };
}

export function extractJsonCandidate(result: unknown) {
  const response = extractManagedText(result);
  const fenced = response.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1] ?? response;
  const start = fenced.indexOf('{');
  const end = fenced.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try { return JSON.parse(fenced.slice(start, end + 1)); } catch { return null; }
}

export function extractManagedText(result: unknown) {
  const outer = result && typeof result === 'object' ? result as Record<string, unknown> : {};
  const provider = outer.result && typeof outer.result === 'object' ? outer.result as Record<string, unknown> : {};
  return typeof provider.response === 'string' ? provider.response : typeof outer.response === 'string' ? outer.response : typeof outer.result === 'string' ? outer.result : '';
}

function escapeHtml(value: string) {
  return value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll('"', '&quot;');
}

function jsData(value: unknown) {
  return JSON.stringify(value).replaceAll('<', '\\u003c').replaceAll('>', '\\u003e').replaceAll('&', '\\u0026');
}

export function buildSeedRows(brief: ProductBrief) {
  const isShiftBoard = brief.compiler.grammar.layoutBias[0] === 'board' && brief.entity.singular === 'Turno';
  const isFocusApp = brief.productName === 'Orbit' && brief.appType === 'project';
  const statuses = brief.appType === 'plants' ? ['Da annaffiare', 'In salute', 'Controlla umidità', 'Cura programmata'] : brief.appType === 'entertainment' ? ['In evidenza', 'In lista', 'Da vedere', 'Già visto'] : isShiftBoard ? ['Da coprire', 'Coperto', 'Cambio richiesto', 'Confermato'] : isFocusApp ? ['Oggi', 'In corso', 'Pianificata', 'Completata'] : ['Attivo', 'In revisione', 'Completato', 'Da contattare'];
  const intentExamples = brief.compiler.intent.domainNouns[0]?.examples ?? [];
  const composedNouns = Array.from({ length: 4 }, (_, index) => intentExamples[index] ?? `${brief.entity.singular} ${['Mattina', 'Pomeriggio', 'Sera', 'Speciale'][index]}`);
  const nouns = brief.appType === 'crm' ? ['Aurora Studio', 'Northstar Labs', 'Lumen SRL', 'Forma Group']
    : brief.appType === 'commerce' ? ['Linea Nova', 'Kit Essenziale', 'Edizione Pro', 'Starter Pack']
      : brief.appType === 'shopping' ? ['Frutta e verdura', 'Detersivo ecologico', 'Caffè', 'Pane integrale']
      : brief.appType === 'plants' ? ['Monstera Alba', 'Ficus Lyrata', 'Pothos Neon', 'Sansevieria']
      : brief.appType === 'entertainment' ? ['Encanto', 'Il Re Leone', 'Toy Story', 'Lilo & Stitch']
      : brief.appType === 'booking' ? ['Giulia Rossi', 'Marco Bianchi', 'Elena Costa', 'Luca Romano']
        : isShiftBoard ? ['Pranzo', 'Cena', 'Weekend', 'Evento speciale']
          : isFocusApp ? ['Priorità del giorno', 'Preparare la proposta', 'Sessione focus', 'Revisione settimanale'] : composedNouns;
  return nouns.map((noun, rowIndex) => Object.fromEntries(brief.entity.fields.map((item, fieldIndex) => {
    if (item.type === 'status') return [item.key, statuses[rowIndex % statuses.length]];
    if (brief.appType === 'plants' && item.key === 'species') return [item.key, ['Monstera deliciosa', 'Ficus lyrata', 'Epipremnum aureum', 'Dracaena trifasciata'][rowIndex]];
    if (brief.appType === 'plants' && item.key === 'location') return [item.key, ['Soggiorno', 'Studio', 'Cucina', 'Camera'][rowIndex]];
    if (brief.appType === 'entertainment' && item.key === 'category') return [item.key, ['Animazione', 'Classico', 'Pixar', 'Avventura'][rowIndex]];
    if (brief.appType === 'entertainment' && item.key === 'year') return [item.key, [2021, 1994, 1995, 2002][rowIndex]];
    if (brief.appType === 'entertainment' && item.key === 'collection') return [item.key, ['Disney Animation', 'Classici Disney', 'Pixar', 'Disney Animation'][rowIndex]];
    if (brief.appType === 'entertainment' && item.key === 'rating') return [item.key, [4.8, 4.9, 4.9, 4.7][rowIndex]];
    if (isShiftBoard && item.key === 'area') return [item.key, ['Sala', 'Cucina', 'Pass', 'Bar'][rowIndex]];
    if (isFocusApp && item.key === 'category') return [item.key, ['Personale', 'Lavoro', 'Focus', 'Review'][rowIndex]];
    if (item.type === 'number') return [item.key, brief.appType === 'plants' ? [38, 72, 49, 64][rowIndex] : (rowIndex + 1) * (fieldIndex + 3) * 120];
    if (item.type === 'date') return [item.key, brief.appType === 'plants' ? ['2026-08-27', '2026-08-28', '2026-08-26', '2026-08-29'][rowIndex] : `2026-${String((rowIndex % 9) + 1).padStart(2, '0')}-${String(10 + rowIndex).padStart(2, '0')}`];
    if (item.type === 'email') return [item.key, `${noun.toLowerCase().replace(/[^a-z0-9]+/g, '.')}@example.test`];
    return [item.key, fieldIndex === 0 ? noun : `${item.label} ${rowIndex + 1}`];
  })));
}

