function openDetail(item){if(!item)return;currentItemId=Number(item.id);$('#detail-title').textContent=String(item[config.entity.fields[0]?.key]||config.entity.singular);for(const field of config.entity.fields){const input=$('#detail-form [name="'+field.key+'"]');if(input)input.value=item[field.key]??'';}$('#detail-error').textContent='';$('#detail').showModal();document.documentElement.classList.add('editor-open');}
function hydrateSurfaceLinks(){const firstKey=config.entity.fields[0]?.key;document.querySelectorAll(surfaceSelector).forEach(surface=>{const title=surface.querySelector('strong')?.textContent?.trim();let item=items.find(record=>String(record.id)===surface.dataset.recordId);if(!item&&title)item=items.find(record=>String(record[firstKey]??'').trim()===title);if(item){surface.dataset.recordId=String(item.id);const heading=surface.querySelector('strong');if(heading)heading.textContent=String(item[firstKey]??heading.textContent);}if(surface.dataset.detailBound)return;surface.dataset.detailBound='true';surface.setAttribute('role','button');surface.setAttribute('tabindex','0');surface.addEventListener('click',event=>{if(event.target instanceof Element&&event.target.closest('.delete'))return;openDetail(items.find(record=>String(record.id)===surface.dataset.recordId))});surface.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openDetail(items.find(record=>String(record.id)===surface.dataset.recordId))}})});}
