async function load(){const [records,metrics]=await Promise.all([api('/api/items'),api('/api/metrics')]);items=records.items;const total=$('#metric-total'),active=$('#metric-active'),workflows=$('#metric-workflows');if(total)total.textContent=metrics.total;if(active)active.textContent=metrics.active;if(workflows)workflows.textContent=metrics.workflows;render();}
