const editor=$('#editor'),detail=$('#detail');const updateModalState=()=>document.documentElement.classList.toggle('editor-open',editor.open||detail.open);const openEditor=()=>{editor.showModal();updateModalState()};const closeEditor=()=>{editor.close();updateModalState()};const closeDetail=()=>{detail.close();updateModalState()};$('#new-item').addEventListener('click',openEditor);$('#close').addEventListener('click',closeEditor);$('#detail-close').addEventListener('click',closeDetail);$('#detail-delete').addEventListener('click',async()=>{if(!currentItemId)return;await api('/api/items/'+currentItemId,{method:'DELETE'});detail.close();currentItemId=null;await load()});editor.addEventListener('close',updateModalState);detail.addEventListener('close',updateModalState);$('#search').addEventListener('input',render);document.querySelectorAll('.nav-item,.mobile-tab').forEach(button=>button.addEventListener('click',()=>{const section=Number(button.dataset.section||0);document.querySelectorAll('.nav-item,.mobile-tab').forEach(item=>{item.classList.toggle('active',item.dataset.section===String(section));if(item.dataset.section===String(section))item.setAttribute('aria-current','page');else item.removeAttribute('aria-current')});(section===0?document.querySelector('.product-view'):$('#database-view'))?.scrollIntoView({behavior:'smooth',block:'start'})}));
